function UIHomeMain:Awake()
    self.controller.MarkPoolable = true
    Events.Broadcast(Constants.EventNames.HomeSceneCheckExtraSceneShowState)
    self.entryWelfareInfoTrans = self.BeginnerEventBtn.transform.parent:Find("BtnOnboardingBenefits")
    self.whiteLevelGiftTrans = self.BtnSign.transform.parent:Find("BtnMind")
    self.btnLimitedTimeSale = self.HideGroup.transform:Find("BtnLayout/BtnLimitedTimeSale")
    if self.whiteLevelGiftTrans then
        SetButtonAction(self.whiteLevelGiftTrans, function()
            local WelfareConstants = import("Game.UI.Welfare.WelfareConstants")
            self:OpenDialogAction(Constants.UITypeIds.UIWelfareMainDialog, { { id = Constants.UITypeIds.UIHomeView } }, { selectedIndex = WelfareConstants.OpenIds.WhiteLevelGift })
        end)
        self.whiteLevelGiftTextTrans = self.whiteLevelGiftTrans:Find("BtnRoot/ImgTime/TxtTime")
    end
    local onlineRewardButton = self.PlayerNode.transform.parent:Find("BtnTopRoot/BtnOnlineReward")
    if onlineRewardButton then
        ---@type OnlineRewardButton
        local env = CfUtils.GetLuaScr(onlineRewardButton, 'Game.Entry.OnlineRewardButton')
        env:AddListener()
    end
    local mainlandBackRewardTrans = self.PlayerNode.transform.parent:Find("BtnTopRoot/BtnRegressionReward")
    if mainlandBackRewardTrans then
        CfUtils.SetActive(mainlandBackRewardTrans, checkNumber(playerComponent.playerDojo.isVeteran) == 1)
        GameUtils.BindRedPoint(Constants.RedPointConst.MainVeteran, mainlandBackRewardTrans, true)
        SetButtonAction(mainlandBackRewardTrans, function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.CashFeedbackDialog })
        end)
    end
    local rankAllowRewardTrans = self.PlayerNode.transform.parent:Find("BtnTopRoot/BtnRankAllowance")
    if rankAllowRewardTrans then
        ---@type SystemToggleVo
        local vo = CfUtils.SystemToggleVo( Constants.SystemToggleIds.Id278)
        CfUtils.SetActive(rankAllowRewardTrans, vo and checkNumber(vo.switch) == 1)
        GameUtils.BindRedPoint(Constants.RedPointConst.MainVeteranAllowance, rankAllowRewardTrans, true)
        SetButtonAction(rankAllowRewardTrans, function()
            xRecord.record("3-028", "click_allowance")
            UIModule.OpenDialog({ id = Constants.UITypeIds.SalaryPlanDialog })
        end)
    end
    local enterTimeLine = checkNumber(KCookie.Get("IS_WAITING_PLAY_TIME_LINE"))
    self.isWaitingEnterTimeLine = (enterTimeLine == 1)
    KCookie.RemoveAllListener("IS_WAITING_PLAY_TIME_LINE")
    KTool.SetActive(self.OtherButtonPOP, false)
    KTool.SetActive(self.BottomPanel.transform.parent.gameObject, true)
    KTool.SetActive(self.Bg.gameObject, true)
    KTool.SetActive(self.Root.gameObject, true)
    self:ResetFlyAni()
    self._eventName2Listener = {
        --[Constants.EventNames.ActivityTimeLimitedDialogClose] = Bind(self, self.OnCloseTimeLimitedDialogHandler),
        [Constants.EventNames.TriggerGiftRefresh] = Bind(self, self.RefreshBtnGiftBag),
        [Constants.EventNames.HOME_GACHAPON_ACTIVITY_UPDATE] = Bind(self, self.RefreshDrawButton),
        [Constants.EventNames.HomeRefreshHotPointCollectionEntranceIcon] = Bind(self, self.RefreshBtnHotPoint),
        [Constants.EventNames.ActivityHomeIcomRefresh] = Bind(self, self.RefreshBigActivity),
        [Constants.EventNames.PlayerUpdateNewState] = function()
            KTool.SetActive(self.PlayerImgNew, PlayerInfoUtils.CheckNewForPlayer2D())
        end,
        [Constants.EventNames.OVERSEA_ENTRY_WELFARE_INFO] = Bind(self, self.OnPlayerEntryWelfare),
        [Constants.EventNames.WHITE_GIFT_TIME_EVENT] = Bind(self, self.OnPlayerWhiteLevelGift),
        [Constants.EventNames.HideGroupState] = Bind(self, self.RefreshHideGroupState),
        [Constants.EventNames.START_SHOW_BOOM_MOVE] = Bind(self, self.StartShowBoomMoveByType),
        [Constants.EventNames.UIEventHomeShowOrHideHand] = function(isShow, position, isImmediate)
            if isShow then
                KTool.SetActive(self.Hand.gameObject, true)
                CfUtils.PlayAnimation(self.Hand, "OverManegeLoungeStrokeDialog_Hand_Remind")
                local worldPos = position
                local v2 = CfUtils.WorldPosition2UIPosition(worldPos, self.Hand.parent)
                self.Hand.anchoredPosition = Vector2.New(v2.x, v2.y)

            elseif isImmediate then
                KTool.SetActive(self.Hand.gameObject, false)

            else
                CfUtils.PlayAnimation(self.Hand, "OverManegeLoungeStrokeDialog_Hand_Touch")

            end
        end,
        [Constants.EventNames.PlayerHeadDateExpired] = function(event)
            local goodsId = checkInt(event.goodsId)
            local headKind = checkInt(event.headKind)
            ---@type CommonPlayerHeadNode
            local playerHeadNode = self.CommonPlayerHeadNode.Env
            if headKind == Constants.PlayerAvatarItemType.Avatar then
                if goodsId == checkInt(playerHeadNode.avatarId) then
                    self:UpdatePlayerHeadNode_()
                end
            elseif headKind == Constants.PlayerAvatarItemType.AvatarFrame then
                if goodsId == checkInt(playerHeadNode.frameId) then
                    self:UpdatePlayerHeadNode_()
                end
            end
        end,
        ["MoviePlayOver"] = function()
            self.isPlaying = false
        end,
        [Constants.EventNames.ClubGVGCloseTips] = function()
            local parent = self.Root
            local node = parent:Find("OverseaClubGvgJumpTips")
            CfUtils.SetActive(node, false)
        end,
    }
    for eventName, listener in pairs(self._eventName2Listener) do
        Events.AddListener(eventName, listener)
    end

    if isNull(self.BtnGrocery) then
        self.BtnGrocery = self.BtnActivity.transform.parent:Find("BtnGrocery")
    end
    local chatBtnNode = self.PlayerNode.transform.parent:Find("OverseaChatBtnNode")
    if isNotNull(chatBtnNode) then
        local scr = CfUtils.GetLuaScr(chatBtnNode, "Game.OverseaChat.OverseaChatButtonNode")
        if isNotNull(scr) then
            scr:InitRedPoint()
        end
    end
    local chatTrans = self.PlayerNode.transform.parent:Find("OverseaChatBtnNode/Button")
    if chatTrans then
        SetButtonAction(chatTrans.gameObject, function()
            ---聊天功能
            self:OpenDialogAction(Constants.UITypeIds.OverseaChatMainDialog, { { id = Constants.UITypeIds.UIHomeView } }, nil, true)
        end)
    end

    -- 检测抽卡道具是否满足
    local GachaponUtils = import('Game.Gachapon.GachaponUtils')
    GachaponUtils.CheckRedPoint()

    if self.MiddlePanel then
        self.leftBgCover = self.Bg.transform:Find("LeftCover")
        self.rightBgCover = self.Bg.transform:Find("RightCover")
        local touchAction = self.MiddlePanel.transform:Find("Touch")
        SetButtonAction(touchAction, function()
            ---点击事件
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if playerComponent then
                local cardDojo = playerComponent:GetSignboardCardDojo()
                Events.Broadcast(Constants.EventNames.UIEventHomeRoleQuickTapAction, { playerCardId = cardDojo.id, cardId = cardDojo.cardId, skinId = checkNumber(cardDojo.cardSkin) })
            end
        end)
    end
    SetButtonAction(self.BtnShow, Bind(self, self.OnBtnShowClick))
    -- 主线提醒
    self:CheckMainQuestRemind()
    
    local isUseNew = GameUtils.GetPlayerDojo():IsOpenBeginnerActivity(Constants.BeginnerActivityType.NewBeginner) and (not ThirdDownloadManager:IsNotDwonloadingEnd())
    CfUtils.SetActive(self.BeginnerAssemble.gameObject,isUseNew)
    if isUseNew then
        GameUtils.BindRedPoint(Constants.RedPointConst.MainNewBeginner, self.BeginnerAssemble.gameObject, true)
        SetButtonAction(self.BeginnerAssemble.gameObject,Bind(self,self.OnBtnBeginnerAssembleClick))
    end
end

function UIHomeMain:OnFocus(focus)
    if focus then
        ---还原为正交相机
        CfUtils.SetUICameraProjection(false, fieldOfView)
        CfUtils.SetTopRightProjection(PROJECTION.PERSPECTIVE)
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = true })
        local isShow = true --GuideUtils.CheckIsCompleteGuideByModuleId(Constants.GuideModule.MainQuest1_1)

        CfUtils.SetTopCommonActive(false, true)
        local goodsList = {}
        if isShow then
            goodsList = { Constants.Currency.FreeDiamondId, Constants.Currency.HpId }
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            if ServerDifferenceMgr:IsSecondaryCurrencyEnable() then
                goodsList = { Constants.Currency.PayDiamondId, Constants.Currency.FreeDiamondId, Constants.Currency.HpId }
            end
        end
        CfUtils.RefreshTopGoods(goodsList)
        CfUtils.ResetNavigatorCustomBackAction()
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)

        self:RefreshBtnGiftBag()
        self:RefreshHideGroupState(true)
        -- 更新杂货铺兑换红点
        --StoreUtils.UpdateGroceryExchangeRedPoint()
        KCookie.Set("RecoveryBGMID", nil)

        -- 刷新天梯开放时间
        AppService:RefreshLadderPvpTime()
    else
        if not self.isCultivate then
            CfUtils.SetTopRightProjection(PROJECTION.NORMAL)
        end
    end
    Events.Broadcast(Constants.EventNames.RoleTouchable, focus)
    CfUtils.SetCanvasEnabled(self.controller.gameObject, focus)
end

function UIHomeMain:OnShow()
    ---显示主界面场景元素
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.HomeSceneShowSignboard)
        ---@type Engine.UI.SafeAreaPanel
        local safeAreaPanel = KTool.GetComponent(self.Root.gameObject, typeof(CS.Engine.UI.SafeAreaPanel))
        if safeAreaPanel then
            safeAreaPanel:ApplySafeArea()
        end
        local isPopOpenDilog = false
        for i, v in pairs(self.popUpData) do
            local isOpen = v.isOpen()
            if isOpen then
                isPopOpenDilog = true
                break
            end
        end
        ---@type GuideComponent
        local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
        ---@type FeatureSignComponent
        local featureSignComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FeatureSignComponent)
        if not guideComponent:IsInGuiding() then
            ---@type HotPointCollectionComponent
            local hotPointCollectionComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.HotPointCollectionComponent)
            if hotPointCollectionComponent and hotPointCollectionComponent:CheckMoviePopUp(function()
                self.controller.transform:SetScaleXYZ(0, 0, 0)
                Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
                -- CfUtils.SetCanvasEnabled(self.controller.gameObject, false)
            end, function()
                Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = true })
                -- CfUtils.SetCanvasEnabled(self.controller.gameObject, true)
                self.controller.transform:SetScaleXYZ(1, 1, 1)
                Events.Broadcast(Constants.EventNames.START_SHOW_BOOM_MOVE, Constants.UIHomeViewBtnType.HotPointCollection)
                if isPopOpenDilog then
                    UIRaycastBlocker:AddCondition("PopOpenDialogAction")
                end
                while self.boomMoveCo ~= nil do
                    cs_coroutine.yield_return()
                end
                if isPopOpenDilog then
                    UIRaycastBlocker:RemoveCondition("PopOpenDialogAction")
                end
                self:OnShow()
            end) then
                return
            end
            if isNotNull(featureSignComponent) and featureSignComponent:CheckFeatureSign() then
                Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })
                self.controller.transform:SetScaleXYZ(0, 0, 0)
                ----存在签到送礼
                return
            end
            if isPopOpenDilog then
                UIRaycastBlocker:AddCondition("PopOpenDialogAction")
            end
        end
        xTry(function()
            ---播放主界面相机动画
            local isFirstStartGame = KCookie.Get('isFirstStartGame')
            ---@type Game.Native.Animation.AnimationPlayer
            local ui_animator = KTool.GetOrAddComponent(self.controller.gameObject, typeof(AnimationPlayer))
            local isNeedWait = false
            local animatorTargetName = UIHomeView_DefaultAnimationName
            if not isFirstStartGame then
                animatorTargetName = UIHomeView_LoginAnimationName
                isNeedWait = true
                KCookie.Set('isFirstStartGame', 1)
            else
                self.controller.transform:SetScaleXYZ(1, 1, 1)
            end
            if ui_animator then
                ui_animator:Play(animatorTargetName)
                if isNeedWait then
                    while ui_animator.IsPlaying do
                        coroutine.yield()
                    end
                end
            end
            ---添加主界面的动画是否播完的逻辑
            local t = os.time()
            local isFinish = true
            while self.isWaitingEnterTimeLine and isFinish do
                if os.time() - t >= 0.9 then
                    self.isWaitingEnterTimeLine = false
                    isFinish = false
                end
                coroutine.yield()
            end

            --local env = GetLuaBehaviour(self.AdvertScrollView, ScrollNodePath)
            --if isNull(env) then
            --    env:Init()
            --end
            if guideComponent and guideComponent:IsInGuiding() then
                return
            end

            -----@type FeatureSignComponent
            --local FeatureSignComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FeatureSignComponent)
            --if isNotNull(FeatureSignComponent) and FeatureSignComponent:CheckFeatureSign() then
            --    return
            --end
            if isPopOpenDilog then
                UIRaycastBlocker:RemoveCondition("PopOpenDialogAction")
            else
                self._canPopup = true
            end
            local index = 0
            for i, v in pairs(self.popUpData) do
                local isOpen = v.isOpen()
                index = index + 1
                if isOpen then
                    v.OpenFunc()
                    break
                end
            end
        end, function()
            if isPopOpenDilog then
                UIRaycastBlocker:RemoveCondition("PopOpenDialogAction")
            end
        end)
        --[[   if isTriggerGift then
               local isOpen = self:StartOpenTriggerGift()
               if isOpen then
                   isOpenFirstFlush = false
               end
           end

           if isOpenFirstFlush then
               self:OnBtnFirstFlushClick()
           end]]

        local isMakeUpOrder = self:isMakeUpOder()
        if isMakeUpOrder then
            local ProxyPluginName = "PlatformProxy"
            if KTool.UNITY_ANDROID() then
                local SDKCenter = CS.Game.Native.MobileSDK.SDKCenter
                SDKCenter.InvokePlugin(ProxyPluginName, "makeUpOrder", "")
            end
            ---@type SDKService
            local SDKService = import('Game.Entry.SDKService')
            local PayAdjust = SDKService:GetInstance().PayAdjust
            if isNotNull(PayAdjust) then
                PayAdjust(SDKService:GetInstance())
            end
        end
        --- 加载子模块
        self:LoadSubModule()

        self:HandelUnfinishedPVPBattleData()
        AppService:GetInstance():StartCacheMessageTip()
        redPointCom:InvokeCallBack(Constants.RedPointConst.PhoneInvestigate)
    end))
    return coWait
end
