function UIHomeMain:IsOpenFirstFlush()
    local isOpen = CfUtils.IsOpneByFunctionId(166)
    if isOpen then
        ---@ 策划清音说 要通关了1-8后再打脸
        local isPass = QuestConfMgr:GetInstance():IsPassQuest(101080)
        if isPass then
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local firstPay = self:IsUseNewFirstFlush() and playerComponent.playerDojo.overseaNewFirstGift or playerComponent.playerDojo.overseaFirstGift
            if isSet(firstPay, "signDayNumber") then
                local allGet = table.count(firstPay.receiveId) >= 3
                if not allGet then
                    local lastBtnFirstFlushClickTime = checkNumber(CfUtils.GetLocalData("BtnFirstFlushClickTime"))
                    local time = os.time()
                    local t = timestamp_to_time(time)
                    if checkNumber(t.day) ~= checkNumber(lastBtnFirstFlushClickTime) then
                        return true
                    end
                end
            else
                local isFirstOpen = checkNumber(CfUtils.GetLocalData("BtnFirstFlushIsFirstOpen"))
                return isFirstOpen == 0
            end
        end
    end
    return false
end

