---StartShowBoomMoveByType 开始流光动画
---@param BtnType integer 用来区分要飞到那个按钮
---
function UIHomeMain:StartShowBoomMoveByType(BtnType)
    if BtnType == Constants.UIHomeViewBtnType.BtnGiftBag then
        self:StartShowBoomMove(nil, self.BtnGiftBag, 0.4)
    elseif BtnType == Constants.UIHomeViewBtnType.HotPointCollection then
        self:StartShowBoomMove(nil, self.BtnHotPoint, 0.4)
    elseif BtnType == Constants.UIHomeViewBtnType.BtnFirstFlush then
        self:StartShowBoomMove(nil, self.BtnFirstFlush, 0.4)
    elseif BtnType == Constants.UIHomeViewBtnType.LimitedTimeSale then
        self:StartShowBoomMove(nil, self.btnLimitedTimeSale, 0.4)
    elseif BtnType == Constants.UIHomeViewBtnType.ContinuousGift then
        self:StartShowBoomMove(nil, self.BtnContinuousRechargeLimit, 0.4)
    end
end

function UIHomeMain:StartShowBoomMove(startPos, endGo, time)
    self:ResetFlyAni()
    self:StopBoomCo()
    local flyTime = not isNull(time) and time or 0.3
    local startPos = not isNull(startPos) and startPos or CS.UnityEngine.Vector3(0, 0, 0)
    self.boomMoveCo = cs_coroutine.start(function()
        KTool.SetActive(self.UIFX_StartBoom.gameObject, true)
        local UIFX_Number_BoomMove = self.UIFX_Number_BoomMove
        UIFX_Number_BoomMove.transform.localPosition = startPos
        KTool.SetActive(UIFX_Number_BoomMove.gameObject, true)
        cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.4))
        local endPosition = endGo.transform.position
        self._boomMoveAni = UIFX_Number_BoomMove.transform:DOMove(endPosition, flyTime):OnKill(function()
            UIFX_Number_BoomMove.transform.localPosition = startPos
            self._boomMoveAni = nil
            KTool.SetActive(UIFX_Number_BoomMove.gameObject, false)
        end)
        cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(flyTime))
        self.UIFX_EndBoom.position = endPosition
        KTool.SetActive(self.UIFX_EndBoom.gameObject, true)
        cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.6))
        self:ResetFlyAni()
        self.boomMoveCo = nil
    end)
end

function UIHomeMain:StopBoomCo()
    if not isNull(self.boomMoveCo) then
        cs_coroutine.stop(self.boomMoveCo)
        self.boomMoveCo = nil
    end
    if not isNull(self._boomMoveAni) then
        self._boomMoveAni:Kill()
        self._boomMoveAni = nil
    end
end

function UIHomeMain:ResetFlyAni()
    KTool.SetActive(self.UIFX_StartBoom.gameObject, false)
    KTool.SetActive(self.UIFX_Number_BoomMove.gameObject, false)
    KTool.SetActive(self.UIFX_EndBoom.gameObject, false)
end

function UIHomeMain:HandelUnfinishedPVPBattleData()
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    local t = comp:GetUnfinishedPVPBattleData()
    local type = checkNumber(t.pvpType)
    if type <= 0 then
        return
    end

    if type == 2 then
        --好友对战

    elseif type == 3 then
        --竞技场

    elseif type == 4 then
        --天梯。

    elseif type == 5 then
        --歼灭战
        GameUtils.SecondConfirm(localize("是否回到之前的战斗"), function()
            GameUtils.Request(Interfaces.OverseaPlayerConfirmBattleReconnect, {}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                local jsonData = response.data
                jsonData.result = 0
                jsonData.isReconnectOutside = 1
                local RegionQuestMgr = import('Game.UI.FightReady.UIMainChapter.RegionQuestMgr')
                RegionQuestMgr:GetInstance():HandleStartBattleResponse(jsonData)
                comp:ClearUnfinishedPVPBattleData()
            end)
        end, function()
            GameUtils.Request(Interfaces.OverseaPlayerRefuseBattleReconnect, {}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    return
                end
                local jsonData = response.data
                comp:ClearUnfinishedPVPBattleData()
            end)
        end, localize("歼灭战进行中"))
    end
end

function UIHomeMain:SetBtnContinuousPayState()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local isHaveBuy = not isNull(playerDojo.overseaSpecialGift) and isSet(playerDojo.overseaSpecialGift, "signDayNumber")
    if isHaveBuy then
        local allGet = table.count(playerDojo.overseaSpecialGift.receiveId) >= 7  ---说明有首充数据 判定一下是否全部领取
        if not allGet then
            KTool.SetActive(self.BtnContinuousRecharge, true)
            local isCanGetReward = playerDojo.overseaSpecialGift.signDayNumber > table.count(playerDojo.overseaSpecialGift.receiveId)
            local redPointGo = GameUtils.GetRedPointGo(self.BtnContinuousRecharge)
            KTool.SetActive(redPointGo, isCanGetReward)
        end
    else
        KTool.SetActive(self.BtnContinuousRecharge, true)
        local redPointGo = GameUtils.GetRedPointGo(self.BtnContinuousRecharge)
        local lastBtnFirstFlushClickTime = checkNumber(CfUtils.GetLocalData("BtnContinuousRechargeClickTime"))
        local time = os.time()
        local t = timestamp_to_time(time)
        KTool.SetActive(redPointGo, checkNumber(t.day) ~= checkNumber(lastBtnFirstFlushClickTime))
    end
end

