---@param isOpenAd boolean 打开广告
function UIHomeMain:IsOpenAd()
    ---@type ScrollEntryComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.AdvertiseEntryComponent)
    local scrollImages = comp:GetData()
    local adTable = scrollImages
    if isNull(adTable) or #adTable == 0 then
        return false
    end

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id110006)
    if (not isUnlock) then
        return false
    end
    -- 1. 判断是否存在本地天数几率
    local adKey = "OpenAd"
    local day = tostring(CfUtils.GetLocalData(adKey, ""))
    if string.len(day) == 0 then
        return true
    end
    -- 2. 判断取出的天数和当前天数
    local currentDay = os.date('%Y-%m-%d')
    if currentDay > day then
        return true
    end
    return false
end

function UIHomeMain:isMakeUpOder()
    if not (KTool.IsMobile()) then
        return false
    end
    local adKey = "MakeUpOder"
    local lastLoginTime = checkInt(tostring(CfUtils.GetLocalData(adKey, "")))
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComp.playerDojo
    local serverTime = playerDojo:GetLoginServerTime()
    if serverTime > lastLoginTime then
        CfUtils.WriteLocalData(adKey, tostring(serverTime))
        return true
    end
    return false
end
