function UIHomeMain:OnPlayerWhiteLevelGift(smallestTime)
    if CfUtils.IsOpneByFunctionId(Constants.SystemToggleIds.Id1111) then
        CfUtils.SetActive(self.whiteLevelGiftTrans, smallestTime > 0)
        if smallestTime > 0 then
            CfUtils.FillText(self.whiteLevelGiftTextTrans, CfUtils.GetTimeHMS(smallestTime))
        end
    end
end

function UIHomeMain:IsHavePay(playerDojo)
    local firstPay = self:IsUseNewFirstFlush() and playerDojo.overseaNewFirstGift or playerDojo.overseaFirstGift
    if not isNull(firstPay) and isSet(firstPay, "signDayNumber") then
        return true
    end
    return false
end

function UIHomeMain:EventOpenTimeLimitedDialogHandler(needOpen)
    self._needOpenTimeLimitedDialog = needOpen
end

function UIHomeMain:LimitedTimeSaleEntry()
    ---@type PlayerComponent
    local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = PlayerComponent.playerDojo

    local isFirstPay = self:IsHavePay(playerDojo)
    local BtnLimitedTimeSale = self.btnLimitedTimeSale
    if isFirstPay then
        local jsonData = playerDojo.cardStarGifts["1"]
        ---@type CardStarGiftDojo
        local cardStarGiftDojo = PlayerComponent:GetCardStarGiftDojo()

        if checkInt(cardStarGiftDojo.id) == 0 and jsonData then
            cardStarGiftDojo:Fill(jsonData)
        end

        if checkInt(cardStarGiftDojo.id) == 0 then
            CfUtils.SetActive(BtnLimitedTimeSale, false)
            return
        end

        local isBuyAll = true
        for k, v in pairs(cardStarGiftDojo.gifts) do
            if cardStarGiftDojo.buyId < tonumber(k) then
                isBuyAll = false
                break
            end
        end

        if isBuyAll then
            CfUtils.SetActive(BtnLimitedTimeSale, false)
            return
        end

        local imgRedTips = BtnLimitedTimeSale.transform:Find("Root/ImgRedtips")
        KTool.SetActive(imgRedTips, true)

        cardStarGiftDojo:StartTimeDown()

        local TxtTime = imgRedTips.transform:Find("TxtTime")
        if isNull(self._limitedTimeSaleTimeLeftUpdate) then
            self._limitedTimeSaleTimeLeftUpdate = CfUtils.GetOrAddComponent(imgRedTips, typeof(BehaviourAction))
            self._limitedTimeSaleTimeLeftUpdate.UpdateAction = function()
                if cardStarGiftDojo.remainTime <= 0 then
                    CfUtils.SetActive(BtnLimitedTimeSale, false)
                    cardStarGiftDojo:RemoveTimer()
                    self:RemoveLimitedTimeUpdateAction()
                    return
                end
                CfUtils.FillText(TxtTime, CfUtils.GetTimeHMS(cardStarGiftDojo.remainTime))
            end
        end

        CfUtils.SetActive(BtnLimitedTimeSale, true)
        SetButtonAction(BtnLimitedTimeSale, function()
            xRecord.record('3-020')
            self:OpenDialogAction(Constants.UITypeIds.LimitedTimeSaleDialog, { { id = Constants.UITypeIds.UIHomeView } }, nil, true)
        end)
    else
        CfUtils.SetActive(BtnLimitedTimeSale, false)
    end
end

function UIHomeMain:UpdatePlayerHeadNode_()
    ---头像头像框
    if isNull(self.CommonPlayerHeadNode.Env) then
        self.CommonPlayerHeadNode:Init()
    end
    ---@type CommonPlayerHeadNode
    local playerHeadNode = self.CommonPlayerHeadNode.Env
    playerHeadNode:FreshBaseUI()

    ---添加头像上的邮件按钮的逻辑
    local mailTrans = self.PlayerNode.transform:Find("BtnMail")
    if mailTrans then
        GameUtils.BindRedPoint(Constants.RedPointConst.Mail, mailTrans.gameObject, true)
        SetButtonAction(mailTrans, function()
            ---开启邮件
            xRecord.record('3-006')
            self:OpenDialogAction(Constants.UITypeIds.MailBox, { { id = Constants.UITypeIds.UIHomeView } })
        end)
    end
end

function UIHomeMain:OnBtnDirectDraw()
    self._playVideoCo = cs_coroutine.start(function()
        self.isPlaying = false

        if ActivityDirectDrawMgr:IsFirstEnterActivity() then
            self.isPlaying = true
            ActivityDirectDrawMgr:PlayVideo()
        end

        while self.isPlaying do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end

        self:OpenDialogAction(Constants.UITypeIds.UIDirectDrawDialog, { { id = Constants.UITypeIds.UIHomeView } }, {}, false, false)
    end)
end

