--- 添加付费签到的倒计时
function UIHomeMain:AddBtnPaySignCountDown()
    local paidCheckin = GameUtils.GetPlayerDojo().paidCheckin
    local endTime = paidCheckin.buyTime
    if checkInt(paidCheckin.hasBuy)  == 1 then
        endTime = paidCheckin.checkinTime
    end
    if endTime - os.time() <= 0  then
        local TxtTime = self.BtnSingleSignPay.transform:Find("ImgTime/TxtTime")
        local imageTime = TxtTime.transform.parent
        KTool.SetActive(imageTime.gameObject, false)
        return
    end
    local TxtTime = self.BtnSingleSignPay.transform:Find("ImgTime/TxtTime")
    local imageTime = TxtTime.transform.parent
    if not isNull(TxtTime) then
        KTool.SetActive(imageTime.gameObject, true)
        CfUtils.FillText(TxtTime.gameObject, CfUtils.GetTimeHMS(endTime - os.time()))
    end
    local CDTimerModule = CS.Engine.Modules.CDTimerModule
    self._paySignTimer = CDTimerModule:GetInstance():AddCD(1, function(count, id)
        local leftSecondTime = endTime - os.time() 
        if leftSecondTime <= 0 then
            -- 结束
            CDTimerModule.GetInstance():RemoveCD(self._paySignTimer)
            KTool.SetActive(self.BtnSingleSignPay.gameObject, false)
        else
            CfUtils.FillText(TxtTime.gameObject, CfUtils.GetTimeHMS2(leftSecondTime))
        end
    end,  endTime - os.time() + 10000, false, true, true)
    KTool.SetActive(self.BtnSingleSignPay.gameObject, true)
end

--- 添加BtnRoleStage 的倒计时
function UIHomeMain:AddBtnRoleStageCountDown()
    ---@type GatherActivityComponent
    local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GatherActivityComponent)
    if isNull(comp) then
        return
    end
    local leftSecondTime = comp:GetLeftSecondTime()
    if leftSecondTime <= 0 then
        return
    end
    local TxtTime = self.BtnRoleStage.transform:Find("ImgTime/TxtTime")
    local imageTime = TxtTime.transform.parent
    if not isNull(TxtTime) then
        KTool.SetActive(imageTime.gameObject, true)

        CfUtils.FillText(TxtTime.gameObject, CfUtils.GetTimeHMS(leftSecondTime))
    end
    local CDTimerModule = CS.Engine.Modules.CDTimerModule
    self._gatherTimer = CDTimerModule:GetInstance():AddCD(1, function(count, id)
        local leftSecondTime = comp:GetLeftSecondTime()
        if leftSecondTime <= 0 then
            -- 结束
            CDTimerModule.GetInstance():RemoveCD(self._gatherTimer)
            KTool.SetActive(self.BtnRoleStage.gameObject, false)
        else
            CfUtils.FillText(TxtTime.gameObject, CfUtils.GetTimeHMS(leftSecondTime))
        end
    end, leftSecondTime + 10000, false, true, true)
    KTool.SetActive(self.BtnRoleStage.gameObject, true)
    comp:SetRewardsRedPointNum()

    local titleText = self.BtnRoleStage.transform:Find("TitleText")
    local TextComp = CS.UnityEngine.UI.Text
    local text = titleText:GetComponent(typeof(TextComp))
    if not isNull(text) then
        text.text = comp:GetActivityName()
    end
end
