function UIHomeMain:UpdateOtherRedPoint()
    for _, v in pairs(CfUtils.GetCfTable(AutoIds.IdSetting1860) or {}) do
        local systemToggleId = parse_number(v, "id")
        local isUnlock = GameUtils.IsUnlockedBySystemTogId(systemToggleId)
        if isUnlock then
            -- 检测：图鉴红点
            if systemToggleId == Constants.SystemToggleIds.Id907 then
                ---@type IllustratedHandbookComponent
                local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
                illustratedHandbookComp:CheckHandbookMainRedPoint()
                -- 检测：背包红点
            elseif systemToggleId == Constants.SystemToggleIds.Id200 then
                ---@type BackpackComponent
                local backpackComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
                backpackComp:CheckBackpackRedPoint()
            elseif systemToggleId == Constants.SystemToggleIds.Id250 then
                local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                cardComp:UpdateCardFusionRedPoint()
                cardComp:UpdateCardDustRedPoint()
            end
        end
    end
end

--右上控制显示
function UIHomeMain:FillRightTopButtons()
    local isOpen = CfUtils.IsOpneByFunctionId(166)
    if not isOpen then
        KTool.SetActive(self.BtnFirstFlush, false)
    else
        self:RemoveFirstFlushTimer()
        KTool.SetActive(self.BtnContinuousRecharge.gameObject, false)
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local firstPay = self:IsUseNewFirstFlush() and playerComponent.playerDojo.overseaNewFirstGift or playerComponent.playerDojo.overseaFirstGift
        local ImgTime = self.BtnFirstFlush.transform:Find("ImgTime")
        CfUtils.SetActive(ImgTime.gameObject, false)
        if not isSet(firstPay, "signDayNumber") then
            KTool.SetActive(self.BtnFirstFlush, true)
            --KTool.SetActive(self.BtnFirstFlush, false)
            local redPointGo = GameUtils.GetRedPointGo(self.BtnFirstFlush)
            local lastBtnFirstFlushClickTime = checkNumber(CfUtils.GetLocalData("BtnFirstFlushClickTime"))
            local time = os.time()
            local t = timestamp_to_time(time)
            KTool.SetActive(redPointGo, checkNumber(t.day) ~= checkNumber(lastBtnFirstFlushClickTime))
        else
            ---说明有首充数据 判定一下是否全部领取
            local allGet = table.count(firstPay.receiveId) >= 3
            KTool.SetActive(self.BtnFirstFlush, not allGet)
            local redPointGo = GameUtils.GetRedPointGo(self.BtnFirstFlush)
            KTool.SetActive(redPointGo, false)
            ---如果都领取完了 那就显示限时特惠
            if not allGet then
                local isCanGetReward = firstPay.signDayNumber > table.count(firstPay.receiveId)
                if isCanGetReward then
                    KTool.SetActive(redPointGo, true)
                else
                    local lastBtnFirstFlushClickTime = checkNumber(CfUtils.GetLocalData("BtnFirstFlushClickTime"))
                    local time = os.time()
                    local t = timestamp_to_time(time)
                    KTool.SetActive(redPointGo, checkNumber(t.day) ~= checkNumber(lastBtnFirstFlushClickTime))
                end
                self:StartBtnFirstFlushCountDown(firstPay)
            else
                local isOpen = CfUtils.IsOpneByFunctionId(10002)
                if isOpen then
                    self:SetBtnContinuousPayState()
                end
            end
        end
    end

    -- 杂货铺锁定状态
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id252)
    CfUtils.SetActive(self.BtnGrocery, isUnlock)

    --如果有活动
    --KTool.SetActive(self.BtnActivity, true)
    --KTool.SetActive(self.BtnActivity, false)
end

function UIHomeMain:RemoveFirstFlushTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end

function UIHomeMain:StartBtnFirstFlushCountDown(data)
    ---如果签到天数大于3天 就没有倒计时了
    if data.signDayNumber >= 3 then
        return
    end

    local remainTime = data.nextReceiveTime - os.time()
    if remainTime > 0 then
        local ImgTime = self.BtnFirstFlush.transform:Find("ImgTime")
        CfUtils.SetActive(ImgTime.gameObject, true)
        local TxtTime = ImgTime.transform:Find("TxtTime")
        CfUtils.FillText(TxtTime, CfUtils.GetTimeHMS2(checkNumber(remainTime)))
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                CfUtils.FillText(TxtTime, CfUtils.GetTimeHMS2(checkNumber(count)))
            else
                CfUtils.SetActive(ImgTime.gameObject,false)
                self:RemoveFirstFlushTimer()
            end
        end, remainTime, false, true)
    end

end

function UIHomeMain:RefreshBtnGiftBag()
    local isOpen = CfUtils.IsOpneByFunctionId(10001)
    if not isOpen then
        return
    end
    ---@type TriggerGiftComponent
    local triggerGiftComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TriggerGiftComponent)
    local triggerChest = triggerGiftComponent:GetEffectTriggerGift()
    local cacheTriggerChest = triggerGiftComponent:GetCacheTriggerGift()
    local isVisible = triggerChest and #triggerChest > 0 or cacheTriggerChest and #cacheTriggerChest > 0

    local longestTimes = triggerGiftComponent:GetLongestTimes()
    if longestTimes > 0 and isVisible then
        local updateTime = function(count)
            local pathTxtTime = "ImgTime/TxtTime"
            local typeCompTxt = typeof(CS.TMPro.TextMeshProUGUI)
            local transTxt = self.BtnGiftBag:Find(pathTxtTime)
            local compTxt
            if not IsNull(transTxt) then
                compTxt = KTool.GetOrAddComponent(transTxt.gameObject, typeCompTxt)
            end
            if not IsNull(compTxt) then
                local value = CfUtils.GetTimeHMS2(count)
                CfUtils.FillText(compTxt, value)
            end
        end
        updateTime(longestTimes)
        KTool.SetActive(self.BtnGiftBag.gameObject, true) -- 入口显示/隐藏 

        if self.triggerTimers then
            CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.triggerTimers)
            self.triggerTimers = nil
        end
        self.triggerTimers = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count <= 0 then
                KTool.SetActive(self.BtnGiftBag.gameObject, false)
            else
                updateTime(count)
            end
        end, longestTimes, false, true)
    else
        KTool.SetActive(self.BtnGiftBag.gameObject, false)
    end
end

function UIHomeMain:RefreshBtnCardSkin()
    ---@type ActivityCardSkinComponent
    local ActivityCardSkinComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityCardSkinComponent)
    local activityData = ActivityCardSkinComponent:GetActivityData()
    if isNotNull(activityData) and #activityData > 0 then
        ---@type SDKService
        local SDKService = import('Game.Entry.SDKService')
        if (SDKService:GetInstance():IsDuoLe() and checkInt(IS_REVIEW_INT) <= 0) 
        or  (not SDKService:GetInstance():IsDuoLe())  then
            local closeTime = ActivityCardSkinComponent:GetMaxCloseTime()
            local currentTime = os.time()
            if closeTime > currentTime then
                if string.isEmpty(activityData[1].homeIcon) then
                    local ImgDrawCard = self.BtnSkin.transform:Find("ImgDrawCard")
                    KTool.SetActive(ImgDrawCard, false)
                else
                    local fullPath = CfUtils.GetImageFullPath(activityData[1].homeIcon)
                    local ImgDrawCard = self.BtnSkin.transform:Find("ImgDrawCard")
                    KTool.SetActive(ImgDrawCard, true)
                    CfUtils.FillImage(ImgDrawCard, fullPath)
                end
            else
                KTool.SetActive(self.BtnSkin.gameObject, false)
            end
        end
       
    else
        KTool.SetActive(self.BtnSkin.gameObject, false)
    end
end

