function UIHomeMain:RefreshWelfareJumpRedPoint()
    local num = 0
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    local isUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id275) and (not SDKService:IsDmm())
