function UIHomeMain:OnLadderButton()
    local isUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id2019)  ---回响是否解锁
    ---添加pvp事件按钮
    if  ActionUtils.IsLadderPvpUnlocked() or isUnLock then
        ---未解锁时不处理
        local playerDojo = GameUtils.GetPlayerDojo()
        local serverTime = playerDojo:GetServerTime()
        local btnRanked = self.BtnFight.transform.parent:Find("BtnRanked")
        local isInLadderOpenTime, ladderEndTime = AppService:GetInstance():IsInLadderOpenTime(serverTime)
        if isInLadderOpenTime then
            CfUtils.SetActive(btnRanked, true)
            ---@type UIActionPromptUpItemNode
            local upItemNode = CfUtils.GetLuaScr(btnRanked, "Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode")
            if upItemNode then
                upItemNode:AddListener()
                upItemNode:Refresh(localize('天梯竞技场进行中...距离结束: _time_', { _time_ = second_toHHMMSS(checkNumber(ladderEndTime) - serverTime) }))
            end
            SetButtonAction(btnRanked, function()
                self.isCultivate = true
                UIModule.OpenDialog({ id = Constants.UITypeIds.LadderCompetionMainDialog, parameters = {} }, { { id = Constants.UITypeIds.UIHomeView } })
            end)
        elseif isUnLock and playerDojo:IsOpenActionDark() then
            CfUtils.SetActive(btnRanked, true)
            ---@type UIActionPromptUpItemNode
            local upItemNode = CfUtils.GetLuaScr(btnRanked, "Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode")
            if upItemNode then
                upItemNode:AddListener()
                upItemNode:Refresh(localize('噩梦回响挑战关卡开启中.....'))
            end
            SetButtonAction(btnRanked, function()
                self.isCultivate = true
                local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(724)
                if isNotNull(row) then
                    GoodsConfMgr:GetInstance():ExecuteJump(row)
                end
            end)
        else
            CfUtils.SetActive(btnRanked, false)
        end
    end
end

function UIHomeMain:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if GameUtils.isZmFunction() then
            GameUtils.SwitchWaterMark(false)
        end
        ---@type SDKService
        local SDKService = import('Game.Entry.SDKService'):GetInstance()
        if SDKService:IsDmm() or (SDKService:IsDuoLe() and (IS_REVIEW_INT > 0)) then
            CfUtils.SetActive(self.BtnAssociation.gameObject , false)
        end
        ---@type ActivityComponent
        local activityComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityComponent)
        activityComponent:OverseaSyncDataReq(function(activityDojos, jsonData)
            self.activityDojos = activityDojos
            --家具商城红点
            ---@type OverseaStoreMgr
            local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
            OverseaStoreMgr:RefreshRenovateHaveRedPoint(jsonData.avatarMall)
            if isSet(jsonData, "unReadMail") and checkInt(jsonData.unReadMail) >= 0 then
                GameUtils.SetRedPointNum(Constants.RedPointConst.Mail, 1)
            end
            
            if isSet(jsonData,"skinCall") then
                ---@type ActivityCardSkinComponent
                local ActivityCardSkinComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityCardSkinComponent)
                ActivityCardSkinComponent:Initial(jsonData.skinCall)
            end
            
            CfUtils.SetActive(self.BtnDirectDraw, false)
            if self.activityDojos then
                --- 定向召唤活动按钮显示逻辑
                local type = ActivityConstants.ActivityType.DirectDraw
                ---@type ActivityDojo
                local activityDojo = self.activityDojos[ActivityConstants.RemoteActivityName[type]]
                if isTable(activityDojo) then
                    local isActive = checkNumber(activityDojo.startTime) < 0 and checkNumber(activityDojo.endTime) > 0
                    if activityDojo and isActive then
                        ---@type ActivityDirectDrawComponent
                        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityDirectDrawComponent)
                        comp:SetActivityDojo(activityDojo)

                        SetButtonAction(self.BtnDirectDraw, Bind(self, self.OnBtnDirectDraw))
                        CfUtils.FillText(self.BtnDirectDraw.transform:Find("Time/TxtDesc"), CfUtils.GetTimeHMS12(activityDojo.endTime))
                        CfUtils.SetActive(self.BtnDirectDraw.transform:Find("redPoint"), activityDojo.redDotHint == 0)
                        CfUtils.SetActive(self.BtnDirectDraw, true)
                    end
                end
            end

            -- Events.Broadcast(Constants.EventNames.HomeSceneShowSignboard)
            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            local musicPlayerId = checkNumber(CS.Engine.Lib.KCookie.Get("MainChapterFirstPassBGM"))
            if musicPlayerId > 0 then
                CS.Engine.Lib.KCookie.Set("MainChapterFirstPassBGM", 0)
                local vo = CfUtils.GetCfVo(AutoIds.IdSetting899, "MusicPlayerVo", musicPlayerId)
                if vo then
                    print("[BGM] 播放主线首通音乐", vo.musicId)
                    playerComponent:SetCurrentMusicId(vo.id)
                    CriWareUtils.PlayMusicById(vo.musicId)
                else
                    CriWareUtils.PlayRandomBGMFromCDList()
                end
            else
                CriWareUtils.PlayRandomBGMFromCDList()
            end
            -- 释放一级地图
            local RegionQuestMgr = import('Game.UI.FightReady.UIMainChapter.RegionQuestMgr')
            RegionQuestMgr:GetInstance():DelPrimaryMapGo()
            ---@type FeatureSignComponent
            local featureSignComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FeatureSignComponent)
            ---@type GuideComponent
            local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
            if isNotNull(featureSignComponent) and featureSignComponent:HasFeatureSign() and not guideComponent.isInGuiding then
                UINavigationBarRoot.Instance:SetActive(false)
                self.controller.transform:SetScaleXYZ(0, 0, 0)
            else
                UINavigationBarRoot.Instance:SetActive(true)
            end
            self:OnLadderButton()
            self:ClearCookie()
            self:RegisterButtons()
            self:FillRightTopButtons()
            self:RegisterRedPoint()
            self:RefreshTestButton()
            self:RefreshDrawButton()
            self:RefreshPassButton()
            self:FillLockBtns()
            self:RefreshBtnHotPoint()
            self:RefreshBtnCardSkin()
            self:RefreshClubBtnStatus(checkTable(jsonData))
            self:RefreshLimitedTimeContinuousGiftButton()
            self:CheckLimitedTimeContinuousGiftPopup()
            if GameUtils.isAccountBindFunction() then
                xTry(function()
                    ---如果是游客账号
                    --local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                    if playerComponent and checkNumber(playerComponent.playerDojo.hasDrawAccountUpgradeRewards) == 0 then
                        GameUtils.SetRedPointNum(Constants.RedPointConst.AccountBindActivity, 1)
                        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.AccountBindActivity)
                    else
                        GameUtils.SetRedPointNum(Constants.RedPointConst.AccountBindActivity, 0)
                        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.AccountBindActivity)
                    end
                end)
            end
        end)

        -- 为【没有正常执行释放抽卡缓存的逻辑】情况做兜底处理
        ---@type GachaponShared
        local GachaponShared = import('Game.Gachapon.GachaponShared'):GetInstance()
        if GachaponShared:HasLoadModelParentGo() then
            GachaponShared:DisposeAll()
        end
    end))
    return coWait
end

function UIHomeMain:RefreshClubBtnStatus(jsonData)
    local t = self:GetClubBtnConfig()

    local res
    for k, tt in ipairs(t) do
        local btn, func = SafeUnpack(tt)
        if not res and func then
            res = func(jsonData, btn)
        else
            CfUtils.SetActive(btn, false)
        end
    end
end

function UIHomeMain:GetClubBtnConfig()
    if self._clubBtnConfig == nil then
        local transform = self.BtnClub.transform
        self._clubBtnConfig = {
            { transform:Find("BossGVG"), Bind(self, self.RefreshClubGVGBtnStatus) },
            { transform:Find("BossTips"), Bind(self, self.RefreshClubBossBtnStatus) },
        }
    end
    return self._clubBtnConfig
end

function UIHomeMain:RefreshClubGVGBtnStatus(jsonData, btn)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id4006)
    local BossGVG = btn
    if not isUnlock then
        CfUtils.SetActive(BossGVG, false)
        return false
    end
    ---@type ClubGVGConstants
    local ClubGVGConstants = import("Game.UI.Club.GVG.ClubGVGConstants")
    local hasRedPoint = checkNumber(jsonData.clubGvgCurrentType) == ClubGVGConstants.BattingStatus
    ClubUtils.GetClubComp():SetGvgRedPoint(hasRedPoint)
    ClubUtils.GetClubComp():SetClubGvgEndTime(jsonData.clubGvgEndTime)

    local isShow = checkNumber(jsonData.clubGvgCurrentType) == ClubGVGConstants.ApplyStatus or hasRedPoint
    CfUtils.SetActive(BossGVG, isShow)

    local CheckTipsPosition = function(go)
        ---@type OverseaClubGVGJumpTips
        local env = CfUtils.GetLuaScr(go, ClubGVGConstants.LuaPath.OverseaClubGVGJumpTips)
        if isNull(env) then
            return
        end
        env:CheckTipsPosition()
    end

    local parent = self.Root
    local node = parent:Find("OverseaClubGvgJumpTips")
    if hasRedPoint then
        if isNull(node) then
            UICommonUtils.LoadGameObject(ClubGVGConstants.PrefabPath.OverseaClubGvgJumpTips, function(go)
                if isNull(go) then
                    return
                end
                go.name = "OverseaClubGvgJumpTips"
                CheckTipsPosition(go)

            end, parent)
        else
            CheckTipsPosition(node)
        end

        AppService:GetInstance():SetOpenCheckGvgTipsClose(true)
    else
        AppService:GetInstance():SetOpenCheckGvgTipsClose(false)
    end
    CfUtils.SetActive(node, hasRedPoint)

    return isShow
end

function UIHomeMain:RefreshClubBossBtnStatus(jsonData, btn)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id4001)
    local BossTips = btn
    if not isUnlock then
        CfUtils.SetActive(BossTips.gameObject, false)
        return false
    end
    if self.isSetClubBoss then
        return true
    end

    local scheduleId = checkNumber(jsonData.clubBossScheduleId)
    KTool.SetActive(BossTips.gameObject, scheduleId > 0)
    ---@type ClubBossPassVo
    local BigBoss = nil
    if scheduleId > 0 and not self.isSetClubBoss then
        for _, bossPassVo in ipairs(ClubUtils.GetPassPassVoByScheduleId(scheduleId)) do
            if bossPassVo.bossTypes == ClubUtils.BossType.BigBoss then
                BigBoss = bossPassVo
                break
            end
        end
        if not isNull(BigBoss) then
            local bossData = QuestConfMgr:GetInstance():GetAllQuestLineupVo(BigBoss.refId)
            for i, v in pairs(bossData) do
                for k, j in pairs(v.wave1NpcType) do
                    if tonumber(j) == Constants.RoleClass.Boss then
                        local bossId = v.wave1NpcId[k]
                        local monster = CardConfMgr:GetInstance():GetBaseMonstVo(bossId)
                        if not isNull(monster) then
                            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(monster.skinId)
                            if not isNull(skinVo) then
                                CfUtils.FillImage(BossTips.transform:Find("Mask/ImgBossHead"), skinVo.buffHead)
                                self.isSetClubBoss = true
                            end
                        end
                    end
                end
            end
            return true
        end
    end
    return false
end

function UIHomeMain:FillLockBtns()
    local unlockState = 1
    local lockedState = 2

    local t = {
        ---      系统功能表id                    按钮              SwitchImageName
        { Constants.SystemToggleIds.Id100, self.BtnCultivate, "BtnCultivate" }, --- 养成
        { Constants.SystemToggleIds.Id204, self.BtnTask, "BtnTask" }, --- 日常任务
        { Constants.SystemToggleIds.Id4001, self.BtnClub, "BtnClub" }, --- 社团
        --{ Constants.SystemToggleIds.ID4002, self.BtnAssociation, "BtnAssociation"}, -- 社群入口
        { Constants.SystemToggleIds.Id3001, self.BtnCafe, "BtnCafe" }, --- 餐厅
        { Constants.SystemToggleIds.Id6004, self.BtnTalent, "BtnTalent" }, --- 作战能力
        { Constants.SystemToggleIds.Id2001, self.BtnFight, "BtnFight" }, --- 副本关卡
    }

    local toggleId2IsUnlock = {}
    for index, value in ipairs(t) do
        local toggleId, btn, switchImgName = SafeUnpack(value)
        local isUnlock = GameUtils.IsUnlockedBySystemTogId(toggleId)
        CfUtils.SetUISwitchImage(btn.transform:Find(switchImgName), isUnlock and unlockState or lockedState)
        toggleId2IsUnlock[toggleId] = isUnlock
    end

    local isUnlockClub = toggleId2IsUnlock[Constants.SystemToggleIds.Id4001]
    CfUtils.SetUISwitchImage(self.BtnClub.transform:Find("BtnClub"), isUnlockClub and 1 or 2)
    CfUtils.SetUISwitchText(self.BtnClub.transform:Find("TxtName"), isUnlockClub and 1 or 2)

    ---@type MaidCoffeeComponent
    local maidCoffeeComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isHaveMenuSell = maidCoffeeComp:IsHaveMenuSell()
    local isUnlockCafe = toggleId2IsUnlock[Constants.SystemToggleIds.Id3001]
    CfUtils.SetActive(self.BtnCafe.transform:Find("Normal"), isHaveMenuSell)
    CfUtils.SetActive(self.BtnCafe.transform:Find("Lock"), isUnlockCafe and (not isHaveMenuSell))
    CfUtils.SetActive(self.BtnCafe.transform:Find("DescGroup"), isUnlockCafe)
    self:SetCafeStar()

end

function UIHomeMain:SetCafeStar()
    ---@type MaidCoffeePlayerComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local cafeStarLevel = component:GetCafeStarLevel()
    for i = 1, 5 do
        local star = self.BtnCafe.transform:Find("DescGroup/ImgStar" .. i)
        if star then
