function UIHomeMain:RefreshDrawButton()
    local drawBtnImg = self.BtnDrawCard.transform:Find('ImgFrame')
    if isNull(drawBtnImg) then
        return
    end

    local GachaponUtils = import('Game.Gachapon.GachaponUtils')
    local gachaponComp = GachaponUtils.GetGachaponComp()
    local gachaHomeDatas = gachaponComp:GetHomeActivityDatas()
    local nowTimeStamp = checkInt(TimeZoneUtils.UtcSeconds)--取出当前的年月日

    local GachaponConstants = import('Game.Gachapon.GachaponConstants')
    local homeActivityName = GachaponConstants.GachaponHomeDefaultName
    for _, activityData in ipairs(gachaHomeDatas) do
        -- 筛选当前处于活动期间内的
        if nowTimeStamp >= activityData.startTime and nowTimeStamp < activityData.endTime then
            homeActivityName = tostring(activityData.entrance)
            break
        end
    end
    local homeAccountName = nil
    for _, activityData in ipairs(gachaHomeDatas) do
        if activityData.poolType == GachaponConstants.PoolType.OverseaAccount then
            homeAccountName = tostring(activityData.entrance)
            break
        end
    end
    if homeActivityName == GachaponConstants.GachaponHomeDefaultName and homeAccountName ~= nil then
        homeActivityName = homeAccountName
    end

    local callBtnImgPath = string.format(GachaponConstants.GachaponHomeActivityPath, homeActivityName)
    if self.callBtnImgPath_ ~= callBtnImgPath then
        self.callBtnImgPath_ = callBtnImgPath
        CfUtils.FillImage(drawBtnImg, callBtnImgPath)
    end
end

