function UIHomeMain:RefreshBigActivity()
    local ActivityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
    ---@type ActivityComponent
    local activityComponent = ActivityMgr:GetActivityComponent()
    local activityData = activityComponent:GetActivityData()
    ---@type ActivityConstants
    local ActivityConstants = import("Game.Activity.ActivityConstants")
    local BigActivityType = ActivityConstants.BigActivityType
    local activityMap = {}
    for k, v in pairs(BigActivityType) do
        activityMap[tostring(v)] = 1
    end
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local currentTime = playerComponent:GetPlayerDojo():GetServerTime()
    local closeTime
    if isNotNull(activityData) and #activityData > 0 and (not ThirdDownloadManager:IsNotDwonloadingEnd()) then
        for k, v in pairs(activityData) do
            if checkInt(v.mainHomeShow) == 1 then
                closeTime = v.endTime
                if closeTime > currentTime then
                    self.bigActivityNodes[tostring(v.id)] = { node = nil, data = v }
                end
            end
        end
        for k, v in pairs(self.bigActivityNodes) do
            local name = "BtnBigActivityGroup_" .. v.data.id
            local parentTrans = self.BtnBigActivityGroup.transform.parent.transform
            local go = parentTrans:Find(name)
            if isNull(go) then
                if isNull(v.node) then
                    go = KTool.Instantiate(self.BtnBigActivityGroup.transform.parent.gameObject, self.BtnBigActivityGroup.gameObject, false)
                    go.name = "BtnBigActivityGroup_" .. v.data.id
                    go.transform:SetAsFirstSibling()
                else
                    go = v.node
                end
            end

            KTool.SetActive(go, true)
            v.node = go
            ---@type UIHomeMainBigActivity
            local env = CfUtils.GetLuaScr(v.node, "Game.Main.UIHomeMainBigActivity")
            env:SetActivityData(v.data)
            env:InitUI()
            env:AddTimer()
            -- env:SetBackClick(Bind( self,self.SetReverseButtonAction))
        end
    end
end
function UIHomeMain:LoadSubModule()
    xTry(function()

        local yield_return = cs_coroutine.yield_return

        local LoadPrefab = function(conf, response)
            local entryShowCondition = conf and conf.entryShowCondition or nil
            local isShowEntry = entryShowCondition == nil or entryShowCondition(response and response.data or {})
            if not isShowEntry then
                return
            end

            local prefabPath = conf.prefabPath
            local parentName = conf.parentName
            local parent = self[parentName]
            if parent == nil then
                printError("parentName %s not found", parentName)
                return
            end
            return cs_coroutine.start(function()
                xTry(function()
                    local go = GameUtils.LoadBundleAsync(prefabPath, parent.gameObject, nil, true)

                    local env = CfUtils.GetLuaScr(go.gameObject, conf.behaviourPath)
                    if not isNull(env) then
                        env:RefreshUI(response)
                    end
                    -- table.insert(self.subModuleLoader, loader)
                end, function()
                    printError("%s", debug.traceback())
                end)
            end)
        end

        for uiTypeId, conf in pairs(SubModuleConf) do
            if GameUtils.IsUnlockedBySystemTogId(conf.systemToggleId) then
                local request = conf.request
                if request then
                    if conf.responseCache and conf.responseCache() then
                        local co = LoadPrefab(conf, conf.responseCache())
                        if co then
                            yield_return(co)
                        end
                    else
                        GameUtils.Request(request, conf.requestParams or {}, function(_, response)
                            if checkNumber(response.errCode) == 0 then
                                local co = LoadPrefab(conf, response)
                                if co then
                                    yield_return(co)
                                end
                            end
                        end)
                    end
                else
                    local co = LoadPrefab(conf)
                    if co then
                        yield_return(co)
                    end
                end
            end
        end
    end)
end

