function UIHomeMain:OnBtnShowClick()
    local isShowUI = not self._isShowUI

    local particleSystemRenders
    if self._isShowUI then
        --- 每次从显示切换到不显示的时候动态获取一次 防止主界面有动态创建的粒子
        ---@type UnityEngine.ParticleSystemRenderer[]
        particleSystemRenders = self.Root.gameObject:GetComponentsInChildren(typeof(CS.UnityEngine.ParticleSystemRenderer))
        self._particleSystemRenders = particleSystemRenders
    else
        particleSystemRenders = self._particleSystemRenders
    end
    local isNotNull = isNotNull
    if isNotNull(particleSystemRenders) then
        for i = 0, particleSystemRenders.Length - 1 do
            ---@type UnityEngine.ParticleSystemRenderer
            local ps = particleSystemRenders[i]
            if isNotNull(ps) then
                ps.enabled = isShowUI
            end
        end
    end

    self._isShowUI = isShowUI
    ----当前是猫还是人
    local state = checkNumber(CfUtils.GetLocalData(Constants.UICacheDataKeys.HOME_BOARD_STATE, "1"))

    local isShowNekoC = state == ModelType.Cover
    if isShowNekoC then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting109, "CardDrawingPosVo", self.roleSkinId)
        if not isNull(vo) and not isNull(vo.copyright) and vo.copyright ~= "" then
            KTool.SetActive(self.ImgNekoC.gameObject, true)
            CfUtils.FillImage(self.ImgNekoC.gameObject, vo.copyright)
        end
    else
        KTool.SetActive(self.ImgNekoC.gameObject, false)
    end

    GameUtils.UpdateUIShowState(self.Root.gameObject, self._isShowUI)
    GameUtils.UpdateUIShowState(self.Bg.gameObject, self._isShowUI)

    UINavigationBarRoot.Instance:SetActive(self._isShowUI)
    local state = self._isShowUI and 2 or 1
    CfUtils.SetUISwitchImage(self.BtnShowState, state)
end

