function UIHomeMain:ShowAndFreshCover(state, skinId)
    if self.MiddlePanel then
        local isVisible = state == 3 --是否立绘图资源
        KTool.SetActive(self.MiddlePanel.gameObject, checkBool(isVisible))
        KTool.SetActive(self.ImgNekoC.gameObject, false)
        if isVisible then
            KTool.SetActive(self.BossDrawingNode.gameObject, true)
            local animationType = KTool.GetComponent(self.BossDrawingNode.gameObject, typeof(CS.UnityEngine.Animation))
            if animationType then
                animationType:Play(AnimationName)
            end
            self.BossDrawingNode:Execute(skinId)
            self.roleSkinId = skinId
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting109, "CardDrawingPosVo", self.roleSkinId)
            if not isNull(vo) and not isNull(vo.copyright) and vo.copyright ~= "" then
                KTool.SetActive(self.ImgNekoC.gameObject, true)
                CfUtils.FillImage(self.ImgNekoC.gameObject, vo.copyright)
            end
        end
        if self.leftBgCover and self.rightBgCover then
            ---@type CardConfMgr
            local cardConfMgr = CardConfMgr:GetInstance()
            ---@type CardSkinVo
            local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
            if cardSkinVo then
                local uiCover = checkNumber(cardSkinVo.uiCover)
                ---@type TableML.TableFileRow
                local row = CfUtils.GetCfLine(AutoIds.IdSetting6413, uiCover)
                if row then
                    local alpha = checkNumber(row:Get("alpha"))
                    local color = tostring(row:Get("color"))
                    color = XLuaUtils.HexToColor(color)
                    CfUtils.SetImageColor(self.leftBgCover, Color.New(color.r, color.g, color.b, alpha / 255))
                    CfUtils.SetImageColor(self.rightBgCover, Color.New(color.r, color.g, color.b, alpha / 255))
                else
                    local alpha = 130
                    local color = '212121'
                    color = XLuaUtils.HexToColor(color)
                    CfUtils.SetImageColor(self.leftBgCover, Color.New(color.r, color.g, color.b, alpha / 255))
                    CfUtils.SetImageColor(self.rightBgCover, Color.New(color.r, color.g, color.b, alpha / 255))
                end
            else
                ---初始值
                local alpha = 130
                local color = '212121'
                color = XLuaUtils.HexToColor(color)
                CfUtils.SetImageColor(self.leftBgCover, Color.New(color.r, color.g, color.b, alpha / 255))
                CfUtils.SetImageColor(self.rightBgCover, Color.New(color.r, color.g, color.b, alpha / 255))
            end
        end
    end
end

function UIHomeMain:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local nodeTrans = self.controller.transform:Find("CommonMainlineTaskTipsNode")
        if not isNull(nodeTrans) then
            KTool.SafeDelete(nodeTrans.gameObject, true)
        end
        local onlineRewardButton = self.PlayerNode.transform.parent:Find("BtnTopRoot/BtnOnlineReward")
        if onlineRewardButton then
            ---@type OnlineRewardButton
            local env = CfUtils.GetLuaScr(onlineRewardButton, 'Game.Entry.OnlineRewardButton')
            if env then
                env:RemoveListener()
            end
        end
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Strengthen)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Quest)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.BeginnerEvent)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Entrust)
        --GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.ResidentEvent)
        -- GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Friend)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Shop)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Other)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.GatherActivity)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneInvestigate)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Phone)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.CatHouse)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Regress)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.BattlePass)
        --GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.FirstPay)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Welfare)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Task)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Club)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Association)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.OverseaPaidCheckin)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.RecommendCard)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Gachapon)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainCafe)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.OverseaChat)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.OverseaEntryWelfare)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Mail)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainVeteran)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainVeteranAllowance)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainRegressionNew)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainNewBeginner)
        for _, redPoint in ipairs(taskEntryRedDefine) do
            GameUtils.RemoveRedPointCallBack(redPoint)
        end

        for _, redPoint in ipairs(activityRedDefine) do
            GameUtils.RemoveRedPointCallBack(redPoint)
        end

        KCookie.Set("IsInUIHomeMain", 0)
        for eventName, listener in pairs(self._eventName2Listener) do
            Events.RemoveListener(eventName, listener)
        end
        self._eventName2Listener = nil

        if self.continuousPayTimer then
            CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.continuousPayTimer)
            self.continuousPayTimer = nil
        end
        if self._paySignTimer then
            CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self._paySignTimer)
            self._paySignTimer = nil
        end
        if self.triggerTimers then
            CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.triggerTimers)
            self.triggerTimers = nil
        end
        if self._playVideoCo then
            cs_coroutine.stop(self._playVideoCo)
            self._playVideoCo = nil
        end
        self:RemoveFirstFlushTimer()
        self:RemoveNewPlayerUpdateAction()
        self:RemoveLimitedTimeUpdateAction()
        self:RemoveSubModuleLoaders()
        self:RemoveLimitedTimeContinuousGiftTimer()
        self:RemoveMainQuestRemindTimer()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

---IsUseNewFirstFlush 是否使用新版的首充  策划说先写死使用新首充
function UIHomeMain:IsUseNewFirstFlush()
    return true
end

function UIHomeMain:OpenNewFirstFlush()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent.playerDojo
    local isFinish = checkNumber(playerDojo.overseaNewFirstGift.beforeReceiveStatus) == 1
    if isFinish then
        self:SaveBtnFirstFlushLocalData()
        self:OpenDialogAction(Constants.UITypeIds.InvestNewPopup, { { id = Constants.UITypeIds.UIHomeView } }, nil, true)
    else
        GameUtils.Request(Interfaces.OverseaBeforeFirstGift, {}, function(request, response)
            if checkInt(response.errCode) == 0 then
                local responseData = response.data
                playerDojo:UpdateBeforeReceiveStatus(1)
                if table.count(responseData.rewards) > 0 then
                    GoodsUtils.DrawRewards(responseData.rewards, true)
                    UIModule.OpenDialog({ id = Constants.UITypeIds.InvestNewThankDialog, parameters = { info = {} } },
                            {
                                { id = Constants.UITypeIds.UIHomeView },
                            })
                end

            end
        end)
    end
end

function UIHomeMain:RefreshLimitedTimeContinuousGiftButton()
    local data = ActivityMgr:GetPayTimeChestData()
    if data and checkInt(data.endTime) > 0 then
        CfUtils.SetActive(self.BtnContinuousRechargeLimit, true)
        self:StartLimitedTimeContinuousGiftTimer()
        SetButtonAction(self.BtnContinuousRechargeLimit, function()
            self:OpenLimitedTimeContinuousGiftDialog()
            --CfUtils.DialogOpen(Constants.UITypeIds.LimitedTimeContinuousGiftDialog, nil, {UIArgs(Constants.UITypeIds.UIHomeView)})
        end)
    else
        CfUtils.SetActive(self.BtnContinuousRechargeLimit, false)
    end
end

function UIHomeMain:RemoveLimitedTimeContinuousGiftTimer()
    if self._limitedTimeContinuousGiftTimer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self._limitedTimeContinuousGiftTimer)
        self._limitedTimeContinuousGiftTimer = nil
    end
end

function UIHomeMain:StartLimitedTimeContinuousGiftTimer()
    local data = ActivityMgr:GetPayTimeChestData()
    local remainTime = checkNumber(data.endTime)
    if remainTime > 0 then
        local ImgTime = self.BtnContinuousRechargeLimit.transform:Find("ImgTime")
        CfUtils.SetActive(ImgTime.gameObject, true)
        local TxtTime = ImgTime.transform:Find("TxtTime")
        CfUtils.FillText(TxtTime, CfUtils.GetTimeHMS2(checkNumber(remainTime)))
        self._limitedTimeContinuousGiftTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                CfUtils.FillText(TxtTime, CfUtils.GetTimeHMS2(checkNumber(count)))
            else
                CfUtils.SetActive(self.BtnContinuousRechargeLimit,false)
                self:RemoveLimitedTimeContinuousGiftTimer()
            end
        end, remainTime, false, true)
    end
end

---判断限时连续礼包的打脸，因为数据获取问题，无法走通用打脸逻辑
function UIHomeMain:CheckLimitedTimeContinuousGiftPopup()
    if self._canPopup and self:IsNeedOpenLimitedTimeContinuousGift() then
        self:OpenLimitedTimeContinuousGiftDialog()
    end
end

function UIHomeMain:IsNeedOpenLimitedTimeContinuousGift()
    local data = ActivityMgr:GetPayTimeChestData()
    if data and checkInt(data.endTime) > 0 then
        local playerId = GameUtils.GetPlayerId()
        local key = CfUtils.GetLocalData("OpenLimitedTimeContinuousGift_" .. playerId .. data.activityUuid, 0)
        if checkInt(key) > 0 then
            return false
        else
            return true
        end
    else
        return false
    end
end

function UIHomeMain:OpenLimitedTimeContinuousGiftDialog()
    local data = ActivityMgr:GetPayTimeChestData()
    if data and checkInt(data.endTime) > 0 then
        local playerId = GameUtils.GetPlayerId()
        CfUtils.WriteLocalData("OpenLimitedTimeContinuousGift_" .. playerId .. data.activityUuid, 1)
        CfUtils.DialogOpen(Constants.UITypeIds.LimitedTimeContinuousGiftDialog, nil, { UIArgs(Constants.UITypeIds.UIHomeView) })
    else
        GameUtils.Toast(localize("活动已结束"))
    end
end

