end

function UIHomeMain:CheckMainQuestRemind()
    local guideComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.GuideComponent)
    if guideComponent and guideComponent:IsInGuiding() then return end
    
    local remind = checkInt(CfUtils.CookieLoad(Constants.UICacheDataKeys.MAIN_QUEST_REMIND))
    if remind == MainQuestRemindType.HAND_AND_FRAME or remind == MainQuestRemindType.HAND then
        CfUtils.PlayAnimation(self.MainQuestHand, "OverManegeLoungeStrokeDialog_Hand_Remind")
        CfUtils.SetActive(self.MainQuestHand, true)
    else
        CfUtils.SetActive(self.MainQuestHand, false)
    end

    if remind == MainQuestRemindType.HAND_AND_FRAME or remind == MainQuestRemindType.FRAME then
        CfUtils.SetActive(self.MainQuestImgHighLight, true)
    else
        CfUtils.SetActive(self.MainQuestImgHighLight, false)
    end
    
    if remind == MainQuestRemindType.NONE then
        self:StartMainQuestRemindTimer()
    end
end

function UIHomeMain:StartMainQuestRemindTimer()
    self:RemoveMainQuestRemindTimer()

    local conf = CfUtils.GetCf(AutoIds.IdSetting6589, "MainQuestRemindVo", true)
    local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    for _, v in ipairs(conf) do
        if not questComponent:IsPassLevelById(v.level) then
            if checkInt(v.time) == 0 then
                CfUtils.CookieSave(Constants.UICacheDataKeys.MAIN_QUEST_REMIND, v.type)
                self:CheckMainQuestRemind()
            else
                self._mainQuestRemindTimer = CDTimerModule:GetInstance():AddCD(1, function(count, id)
                    if count == 0 then
                        CfUtils.CookieSave(Constants.UICacheDataKeys.MAIN_QUEST_REMIND, v.type)
                        self:CheckMainQuestRemind()
                    end
                end, checkInt(v.time), false, true, true)
            end
            break
        end
    end
end

function UIHomeMain:RemoveMainQuestRemindTimer()
    if not self._mainQuestRemindTimer then return end
    
    CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self._mainQuestRemindTimer)
    self._mainQuestRemindTimer = nil
end

return UIHomeMain
